const node = String(input.node == null ? '' : input.node).trim();
if (!node) return { success: false, error: 'graph_neighbors 缺 node 參數' };
const d = parseInt(String(input.depth == null ? 1 : input.depth), 10);
const depth = Math.max(1, Math.min(Number.isFinite(d) && d > 0 ? d : 1, 10));
const template = String(input.template == null ? '' : input.template).trim() || 'triplet';
const directed = String(input.directed) === 'true' ? 'true' : 'false';
return { success: true, node: node, node_enc: encodeURIComponent(node),
         depth: String(depth), template: encodeURIComponent(template), directed: directed };

