const machine = String(input.machine || '');
const kbPrefix = 'kb://' + path + '#';
// 🔴 `inkstone/mira#6`（leo 2026-08-18）：path 是**相對於被監看資料夾**的路徑，
//   所以兩台機器上的 `RFP/design.md` 在這裡長得一模一樣 ⇒ 後同步的那台會把
//   前一台的知識**無聲刪掉**（症狀不是「變兩份」，是前面那份消失）。
//   machine 是唯一分得開它們的那一維。規則照抄 arcrun-rag#46 對 library 的做法：
//   **兩邊都有值時才收緊**——payload 沒帶（舊版 daemon）或卡上沒有（改版前的
//   既有資料）都退回原本的行為，既有資料照樣被同一台機器 upsert 掉，不會突然變兩份。
function machineBlocks(theirs) {
  return machine !== '' && theirs !== '' && theirs !== machine;
}
const ab = parse(input.blocks_body);
const entries = (ab && ab.entries) || [];
const dead_entry = [];
const hitMetas = [];
for (const e of entries) {
  let meta = {};
  if (e.metadata_json) { try { meta = JSON.parse(e.metadata_json) || {}; } catch (err) { meta = {}; } }
  const mPath = String(meta.source_path || '');
  const mSrc = String(meta.source || '');
  const hasPath = mPath !== '';
  const hasKbSrc = mSrc.indexOf('kb://') === 0;
  let hit;
  if (hasPath || hasKbSrc) {
    hit = (hasPath && path && mPath === path) || (hasKbSrc && path && mSrc.indexOf(kbPrefix) === 0);
  } else { hit = true; }
  if (hit && machineBlocks(String(meta.machine || ''))) hit = false;
  if (hit && e.id) { dead_entry.push({ id: e.id }); hitMetas.push(meta); }
