// （這裡是獨立沙箱、看不到 prep 算好的值，只能各自維護一份——同 library/machine
// 兩格在這個節點裡的既有做法）。
function isUnresolvedTemplateLocal(v) {
  return typeof v === 'string' && /^\{\{[\w.]+\}\}$/.test(v);
}
const rawPathLocal = input.path;
const srcPath = (rawPathLocal == null || String(rawPathLocal).trim() === '' || isUnresolvedTemplateLocal(rawPathLocal))
  ? (pageName + '.md') : String(rawPathLocal);
const srcUri = 'kb://' + srcPath;
const lib = String(input.library || 'kb');
// 🔴 `inkstone/mira#6`：machine 是**獨立的一格**，不塞進 source_uri。
//   source_uri 的既有意思是「相對於被監看資料夾的路徑」，portal 的 srcLocalPath()
//   直接把 `kb://` 之後整段當本機相對路徑用（console-ui/public/portal/index.html）——
//   把機器名混進去會讓那條路吐出 `youlinhsieh@Leo-MBA/RFP/design.md` 這種不存在的路徑，
//   而且舊資料的第一段（`kb://RFP/...` 的 RFP）會被誤讀成機器名 ⇒ **憑空長出假機器**。
//   分成獨立欄位就沒有這個猜測：舊資料沒有這一格＝誠實地「未知來源」。
const machine = String(input.machine || '');
const machineLabel = String(input.machine_label || '') || machine;
if (!md.trim()) return { success: false, error: 'card_content 為空' };
