// 下次收同一張卡時 pick_stale 靠這三格判斷「雲端那份是不是完整且一模一樣」。
// （#255：card_rels＝第一段自己名下的條數；不分段時就是整張卡的條數，與從前一樣）
const cardHash = String(input.card_hash || '');
for (const b of outBlocks) { b.card_hash = cardHash; b.card_blocks = String(blocks.length); b.card_rels = String(relsSlice.length); }
