if (rawPageName === undefined || rawPageName === null || rawPageName === '' ||
    looksUnsubstituted(rawPageName) || String(rawPageName) === 'unknown') {
  throw new Error('page_name 未代入或缺失（收到：' + JSON.stringify(rawPageName) + '），拒收未代入的樣板字串，不觸發分群');
}
var pageName = String(rawPageName);
var blocks = Array.isArray(input.blocks) ? input.blocks : [];
// c15345（總管實測：00-INDEX 讀回的摘要是「# 頁名」標題行，不是真摘要）：blocks[0]
// 通常只是 H1 標題那個 chunk（parse_card 以標題切塊，「## 摘要」另成一塊）。
// 改成跟 kbdb library-index.ts 的 GLOSS_HEADINGS 同一套慣例去找摘要段
// （兩套段名都收：雲端重萃「## 摘要」／本機 daemon「## 一句話定義」），
// 找不到才退回 blocks[0]（沒有摘要段的卡至少還有個開頭可看）。
