var glossBlock = null;
for (var bi = 0; bi < blocks.length; bi++) {
  var bc = String(blocks[bi].content || '');
  for (var hi = 0; hi < GLOSS_HEADINGS_LOCAL.length; hi++) {
    if (bc.indexOf(GLOSS_HEADINGS_LOCAL[hi]) === 0) { glossBlock = bc; break; }
  }
  if (glossBlock) break;
}
