  return typeof v === 'string' && /^\{\{[\s\S]*\}\}$/.test(v.trim());
}
// inkstone/arcrun-rag#255：分段送的卡，概念歸屬（LLM）只在第一段做一次。
if (String(input.do_blocks) === 'false') {
  throw new Error('分段送的後面幾段：概念歸屬已在第一段處理，這段略過');
}
var md = String(input.card == null ? '' : input.card);
var relSec = /##\s*關聯\s*\n([\s\S]*?)(?=\n#{1,2}(?!#)\s|\n---|$)/.exec(md);
var seen = {};
var entities = [];
if (relSec) {
  var lines = relSec[1].split('\n');
  for (var i = 0; i < lines.length; i++) {
    var m = /^\s*(?:[-*]\s*)?(.+?)\s*>>\s*(.+?)\s*>>\s*(.+?)\s*$/.exec(lines[i]);
    if (!m) continue;
    var pair = [String(m[1] || '').trim(), String(m[3] || '').trim()];
    for (var k = 0; k < pair.length; k++) {
      var e = pair[k];
      if (!e || e === 'knowledge-base' || seen[e]) continue;
      seen[e] = true;
      entities.push(e);
    }
  }
}
if (entities.length === 0) {
  throw new Error('本卡「## 關聯」段沒有可處理的 entity（沒有這段，或裡面沒有 A>>B>>C 格式的行）');
}
var rawLibrary = input.library;
var library = (rawLibrary === undefined || rawLibrary === null || rawLibrary === '' || looksUnsubstitutedLocal(rawLibrary))
  ? 'kb' : String(rawLibrary);
return { success: true, entities_json: JSON.stringify(entities), library: library };

prep.code:
// 🔴 inkstone/arcrun-rag#237（2026-10-05 實撞）：這支做的是**不可逆真刪**，
//   必要輸入缺失、或仍帶著「沒被代換的佔位符」時，必須在刪任何東西**之前**就停。
//   實撞：沒帶 path 觸發 ⇒ 引擎不代換、`{{input.path}}` 以字面字串進來，
//   它不是 falsy（舊的 `input.path || 預設` 不接手），一路查到 `kb://{{input.path}}`
//   並真刪命中的 record。⇒ 兩道：① page_name／path 都必填（不再默默補預設）
//   ② 值裡只要還有 `{{…}}` 就當作沒代換、拒絕。
//   daemon 一直都會送 path（collector/direct.go），正常觸發行為不變。
//   library 是選填的收窄條件（缺了只會殺得更少）；machine 見下方，#273 起必填。
function unresolved(v) { return /\{\{[^}]*\}\}/.test(v); }
const page = String(input.page_name == null ? '' : input.page_name).trim();
if (!page) throw new Error('rag_takedown_direct 缺 page_name，什麼都沒刪');
const path = String(input.path == null ? '' : input.path).trim();
if (!path) throw new Error('rag_takedown_direct 缺 path（原檔路徑），什麼都沒刪');
if (unresolved(page)) throw new Error('rag_takedown_direct 的 page_name 仍是未代換的佔位符（' + page + '），什麼都沒刪');
if (unresolved(path)) throw new Error('rag_takedown_direct 的 path 仍是未代換的佔位符（' + path + '），什麼都沒刪');
// library（arcrun-rag#46）：選填。舊版 daemon 不會送，此時維持原本只看 path 的行為。
const library = String(input.library == null ? '' : input.library).trim();
// machine（`inkstone/mira#6`，leo 2026-08-18）：與 library 同一條規則、同一個理由，
// 只是差一層——library 分得開「同一台機器的兩個資料夾」，machine 分得開「兩台機器」。
// 選填：舊版 daemon 不送，此時行為與從前一字不差。
const machine = String(input.machine == null ? '' : input.machine).trim();
// 🔴 inkstone/arcrun-rag#273（2026-10-18 實撞，#269 c21346）：machine 不帶時引擎不代換，
//   `{{input.machine}}` 以字面字串進來，build_deprecations 拿它去比 meta.machine ⇒ 全部「別台機器」
//   ⇒ 一張都不殺（dead_count 0）、卻只刪了 triplet（triplet 那側不看 machine）：回成功，實際沒下架。
//   machine 因此改為**必填**（現行 daemon 一律會送，collector/direct.go drainPendingTakedowns）。
//   空的 machine 也不放行：空＝不收窄＝會連坐別台機器上同名同路徑的卡（inkstone/mira#6）。
if (!machine) throw new Error('rag_takedown_direct 缺 machine（機器身分，如 youlinhsieh@Leo-MBA），什麼都沒刪');
if (unresolved(machine)) throw new Error('rag_takedown_direct 的 machine 仍是未代換的佔位符（' + machine + '），什麼都沒刪');
// src_uri_enc：list_triplets 要拿它去 KBDB by-source 查「這張卡自己的三元組」，
// CJK 進 URL query 前必先 encodeURIComponent（同 rag_ingest_card 的 prep）。
const srcUri = 'kb://' + path;
// inkstone/arcrun-rag#255：概念卡／分段的三元組有自己的 source_uri（kb://路徑#t=<名字>，
// 見 rag_ingest_card 的 triplet_scope）。帶了 triplet_scope 就只下架那一批；沒帶＝與從前一樣
// （kb://路徑，也就是文件卡本人那一批，連同改版前所有卡共用這個 source_uri 時寫下的）。
const rawScope = input.triplet_scope;
const scope = (rawScope == null || unresolved(String(rawScope))) ? '' : String(rawScope).trim();
const tripSrcUri = scope ? (srcUri + '#t=' + scope) : srcUri;
return { success: true, page_name: page, page_enc: encodeURIComponent(page),
         path: path, path_enc: encodeURIComponent(path), source_uri: srcUri, src_uri_enc: encodeURIComponent(srcUri),
         trip_src_uri: tripSrcUri, trip_src_uri_enc: encodeURIComponent(tripSrcUri),
         library: library, machine: machine };

build_deprecations.code:
function parse(b) { if (typeof b === 'string') { try { return JSON.parse(b); } catch (e) { return null; } } return b; }
const a = parse(input.blocks_body);
const entries = (a && a.entries) || [];
const path = String(input.path || '');
const lib = String(input.library || '');
const mach = String(input.machine || '');
const kbPrefix = 'kb://' + path + '#';
const dead_entries = [];
for (const e of entries) {
  let meta = {};
  if (e.metadata_json) { try { meta = JSON.parse(e.metadata_json) || {}; } catch (err) { meta = {}; } }
  // 2026-08-05 改真刪後拿掉「跳過已 deprecated」：那些舊垃圾正是要清的對象，
  // 留著跳過等於永遠清不掉（實測 youlin 374 blocks 裡有 23 筆）。
  const mPath = String(meta.source_path || '');
  const mSrc = String(meta.source || '');
  const hasPath = mPath !== '';
  const hasKbSrc = mSrc.indexOf('kb://') === 0;
  let hit;
  if (hasPath || hasKbSrc) {
    hit = (hasPath && path && mPath === path) || (hasKbSrc && path && mSrc.indexOf(kbPrefix) === 0);
  } else {
    hit = true;
  }
  // arcrun-rag#46：library 兩邊都有才比；不一致＝別的資料夾的同名檔，不准動。
  const mLib = String(meta.library || '');
  if (hit && lib !== '' && mLib !== '' && mLib !== lib) hit = false;
  // `inkstone/mira#6`：machine 同一條規則（兩邊都有才收緊）。少了這一維，
  // 「A 機器刪掉 notes.md」會把 B 機器上還活著的 notes.md 一起殺掉。
  const mMachine = String(meta.machine || '');
  if (hit && mach !== '' && mMachine !== '' && mMachine !== mach) hit = false;
  if (!hit) continue;
  dead_entries.push({ id: e.id });   // 真刪只需要 id
}
return { success: true, dead_entries: dead_entries, dead_count: dead_entries.length };

pick_dead_triplets.code:
let body = input.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = null; } }
const ids = (body && Array.isArray(body.record_ids)) ? body.record_ids : [];
const dead_records = ids.map(function (id) { return { record_id: id }; });
// total＝KBDB 端不受 limit 影響的命中總數。拿不完（一張卡三元組破千）時
// 留在輸出裡讓執行紀錄看得見，不要靜默少刪。
const total = (body && typeof body.total === 'number') ? body.total : dead_records.length;
return { success: true, dead_records: dead_records, count: dead_records.length,
         total: total, truncated: total > dead_records.length };

