prep_llm.code:
function parse(b) { if (typeof b === 'string') { try { return JSON.parse(b); } catch (e) { return null; } } return b; }
var entities = parse(input.entities_raw);
entities = Array.isArray(entities) ? entities : [];
// KBDB 寫入三元組時會把 subject／object 收斂成標準寫法（kbdb/src/actions/entity-canon.ts 的
// canonicalEntity：NFC、剝 [[X]]／`X` 整串包裝、筆記副檔名路徑取檔名、空白收斂）。
// 查詢（field=subject&value=）不會替你收斂 ⇒ 用卡片裡原樣的 `[[M150]]` 去查，什麼都找不到，
// 等於永遠判成「沒有 description」而重寫。所以這裡先照同一份規則收斂再查、再比對。
// （這是 canonicalEntity 的逐行移植；改那份規則時兩處要一起改——workflows/tests/entity-concept-scope.test.mjs 有向量守著。）
function unwrapWhole(t) {
  var code = /^(`+)([\s\S]*?)(`+)$/.exec(t);
  if (code) { var inner = code[2].trim(); if (inner && inner.indexOf('`') === -1) return inner; }
  if (t.indexOf('[[') === 0 && t.length > 4 && t.slice(-2) === ']]') {
    var w = t.slice(2, -2).trim();
    if (w && w.indexOf('[[') === -1 && w.indexOf(']]') === -1) return w;
  }
  return t;
}
function canon(raw) {
  var fallback = String(raw == null ? '' : raw).trim();
  var t = String(raw == null ? '' : raw);
  if (typeof t.normalize === 'function') t = t.normalize('NFC');
  t = t.trim();
  if (!t) return fallback;
  for (var q = 0; q < 4; q++) { var before = t; t = unwrapWhole(t); if (t === before) break; }
  var NOTE_EXT = /\.(md|markdown|mdx|txt|org)$/i;
  if (NOTE_EXT.test(t)) {
    t = t.replace(NOTE_EXT, '');
    var cut = Math.max(t.lastIndexOf('/'), t.lastIndexOf('\\'));
    if (cut >= 0) t = t.slice(cut + 1);
  }
  t = t.replace(/\s+/g, ' ').trim();
  return t || fallback;
}
var seen = {};
var uniq = [];
for (var i = 0; i < entities.length; i++) {
  var e = canon(entities[i]);
  if (!e || e === 'knowledge-base' || seen[e]) continue;
  seen[e] = true;
  uniq.push(e);
}
if (uniq.length === 0) throw new Error('沒有可處理的 entity（entities_json 空或全被過濾）');

// inkstone/arcrun-rag#267：membership 與 description 的存在判斷，來自 rag_entity_lookup
// 對「這張卡自己的 entity」各查一次的結果（不再撈整個庫）。
//   existingConcept[entity] ＝ 這個 entity 在本庫已有「屬於」（membership，子庫各自記錄——判斷不變）
//   existingDesc[entity]    ＝ 這個 entity 在任何庫已有 description（Arcrun#264，跨庫——判斷不變）
var lookup = parse(input.lookup_body);
var lookupResults = (lookup && Array.isArray(lookup.results)) ? lookup.results : null;
if (!lookupResults) throw new Error('LOOKUP_UNREADABLE：rag_entity_lookup 的回應讀不出 results，不猜（猜錯＝重寫 description）');
var existingConcept = {};
var existingDesc = {};
var knownConcepts = {};     // concept -> [已歸入的 entity]，來自這幾個 entity 自己的既有歸屬
var looked = {};            // entity -> true（查詢成功、有結論）
var truncatedCount = 0;
for (var l = 0; l < lookupResults.length; l++) {
  var lr = lookupResults[l] || {};
  var ld = (lr.data && typeof lr.data === 'object') ? lr.data : lr;
  var lname = String(ld.entity || '');
  if (!lname || lr.success === false) continue;   // 這個 entity 查詢失敗＝這次不處理它（不當成「沒有」）
  looked[lname] = true;
  if (ld.has_desc) existingDesc[lname] = true;
  if (ld.in_lib_concept) existingConcept[lname] = true;
  if (ld.truncated) truncatedCount++;
  var own = Array.isArray(ld.concepts) ? ld.concepts : [];
  for (var oc = 0; oc < own.length; oc++) {
    var oname = String(own[oc] || '');
    if (!oname) continue;
    if (!knownConcepts[oname]) knownConcepts[oname] = [];
    if (knownConcepts[oname].indexOf(lname) === -1) knownConcepts[oname].push(lname);
  }
}

// Arcrun#265：概念目錄（給 LLM 看的「現有概念清單」）讀跨庫查詢結果
// （field=predicate&value=屬於，不帶 library）——不管哪個子庫先用過的概念名稱，
// 這裡都收進目錄，讓 LLM 照抄既有名稱，不會因為換了子庫又重新命名一個同義詞。
// #267：視窗是「最新 100 筆」（64 KiB 天花板下的上限），再補上這幾個 entity 自己已歸入的概念。
var parsedGlobalConcepts = parse(input.global_concepts_body);
var globalConceptRecords = (parsedGlobalConcepts && Array.isArray(parsedGlobalConcepts.records)) ? parsedGlobalConcepts.records : [];
var conceptMembers = {};    // concept(object) -> [members(subject)]，跨庫 hub 目錄
for (var cr = 0; cr < globalConceptRecords.length; cr++) {
  var cv = (globalConceptRecords[cr] && globalConceptRecords[cr].values) || {};
  var csubj = String(cv.subject || '');
  var cobj = String(cv.object || '');
  if (!csubj || !cobj || String(cv.predicate || '') !== '屬於') continue;
  if (!conceptMembers[cobj]) conceptMembers[cobj] = [];
  if (conceptMembers[cobj].indexOf(csubj) === -1) conceptMembers[cobj].push(csubj);
}
for (var kc in knownConcepts) {
  if (!conceptMembers[kc]) conceptMembers[kc] = [];
  for (var km = 0; km < knownConcepts[kc].length; km++) {
    if (conceptMembers[kc].indexOf(knownConcepts[kc][km]) === -1) conceptMembers[kc].push(knownConcepts[kc][km]);
  }
}

// 冪等：只處理「描述或概念歸屬還缺一項」的 entity，同一張卡重送不會重複寫。
// Arcrun#264：todo 只決定「要不要送 LLM」；真正決定「寫哪一半」的是下面
// 每個 entity 各自的 needsDesc／needsConcept 旗標（傳給 parse_llm，各自過濾
// 出只需要的那一半才 POST——不然即使這裡跨庫查到 description 已存在，
// 只是概念缺（本庫沒有），還是會連著把 description 也重寫一次）。
var todo = [];
var flags = {};
var unlooked = 0;
for (var t = 0; t < uniq.length; t++) {
  var name = uniq[t];
  if (!looked[name]) { unlooked++; continue; }   // 沒有查詢結論的 entity 這次不處理
  var needsDesc = !existingDesc[name];
  var needsConcept = !existingConcept[name];
  if (needsDesc || needsConcept) {
    todo.push(name);
    flags[name] = { needsDesc: needsDesc, needsConcept: needsConcept };
  }
}
if (todo.length === 0) {
  if (unlooked > 0 && unlooked === uniq.length) {
    throw new Error('LOOKUP_NO_CONCLUSION：rag_entity_lookup 對本卡全部 ' + unlooked + ' 個 entity 都沒有結論（查詢失敗），這次不處理，不當成沒有 description 去重寫');
  }
  throw new Error('ALL_ALREADY_DESCRIBED：本次 entity 皆已有 description 與屬於關係（或查詢無結論 ' + unlooked + ' 個），不重複寫');
}
var conceptDirLines = [];
for (var c in conceptMembers) {
  conceptDirLines.push('- 「' + c + '」（現有成員：' + conceptMembers[c].slice(0, 8).join('、') + '）');
}
return {
  success: true,
  todo_json: JSON.stringify(todo),
  flags_json: JSON.stringify(flags),
  concept_directory: conceptDirLines.length ? conceptDirLines.join('\n') : '（目前這個庫還沒有任何概念節點）',
  card_snippet: String(input.card_content || '').slice(0, 4000),
  library: String(input.library || 'kb'),
  lookup_unresolved: unlooked,
  lookup_truncated: truncatedCount,
};

ask_llm.prompt:
你是知識圖譜的實體歸類器。下面是一段卡片內容（用來理解實體的背景，不必全部用到）：

{{prep_llm.data.card_snippet}}

要處理的實體清單（每一個都必須輸出，一個不漏）：
{{prep_llm.data.todo_json}}

目前已存在的概念節點目錄（如果某個實體明顯適合歸入其中一個，請完全照抄該概念的名稱字串；只有真的沒有一個合適時才創造一個新的概念名稱，新名稱要是抽象類別，例如「科技公司執行長」，不是具體關係）：
{{prep_llm.data.concept_directory}}

請針對清單裡每一個實體，輸出：
1. description：一句話描述這個實體是什麼（根據上面的卡片內容或你自己的知識，客觀陳述，不要意見、不要臆測未知資訊）。
2. concept：這個實體所屬的抽象概念類別（不是具體關係、不是與其他實體的關係，是它「是一種什麼」的類別）。

只輸出 JSON，格式為陣列，每一項 {"entity":"...","description":"...","concept":"..."}，不要有任何其他文字、不要 markdown code fence、不要前言或說明。

parse_llm.code:
function parse(b) { if (typeof b === 'string') { try { return JSON.parse(b); } catch (e) { return null; } } return b; }
function extractArrayFromText(text) {
  text = String(text == null ? '' : text).trim();
  var fence = /^```(?:json)?\s*([\s\S]*?)\s*```$/.exec(text);
  if (fence) text = fence[1].trim();
  var start = text.indexOf('[');
  var end = text.lastIndexOf(']');
  if (start === -1 || end === -1 || end < start) {
    throw new Error('LLM 輸出裡找不到 JSON 陣列：' + text.slice(0, 300));
  }
  try { return JSON.parse(text.slice(start, end + 1)); } catch (e) {
    throw new Error('LLM JSON 陣列解析失敗：' + String(e) + ' / raw=' + text.slice(0, 300));
  }
}
var arr;
if (Array.isArray(input.llm_response)) {
  arr = input.llm_response;
} else if (typeof input.llm_text === 'string' && input.llm_text) {
  arr = extractArrayFromText(input.llm_text);
} else {
  var content = '';
  try { content = input.llm_choices[0].message.content; } catch (e) { content = ''; }
  arr = extractArrayFromText(content);
}
if (!Array.isArray(arr) || arr.length === 0) throw new Error('LLM 輸出的陣列是空的或不是陣列');
var library = String(input.library || 'kb');
var flags = parse(input.flags_raw) || {};
var descItems = [];
var conceptItems = [];
var itemCount = 0;
for (var j = 0; j < arr.length; j++) {
  var it = arr[j] || {};
  var entity = String(it.entity || '').trim();
  var description = String(it.description || '').trim();
  var concept = String(it.concept || '').trim();
  if (!entity || !description || !concept) continue;
  var f = flags[entity];
  if (!f) continue;   // LLM 吐出沒被要求處理的 entity，忽略（不寫）
  itemCount++;
  if (f.needsDesc) descItems.push({ entity: entity, description: description, library: library });
  if (f.needsConcept) conceptItems.push({ entity: entity, concept: concept, library: library });
}
if (itemCount === 0) throw new Error('LLM 輸出的項目全部缺欄位、或都不在待處理清單裡（entity/description/concept 至少一項空白，或 entity 不在 todo）');
return {
  success: true,
  desc_items: descItems,
  concept_items: conceptItems,
  desc_count: descItems.length,
  concept_count: conceptItems.length,
};

