// canonicalEntity：NFC、剝 [[X]]／`X` 整串包裝、筆記副檔名路徑取檔名、空白收斂）。
// 查詢（field=…&value=）不會替你收斂 ⇒ 用卡片裡原樣的 `[[M150]]` 去查，什麼都找不到，
// 等於永遠判成「沒有 description」而重寫。所以這裡先照同一份規則收斂再查、再比對。
// （這是 canonicalEntity 的逐行移植；改那份規則時兩處要一起改——workflows/tests/entity-concept-scope.test.mjs 有向量守著。）
function unwrapWhole(t) {
  var code = /^(`+)([\s\S]*?)(`+)$/.exec(t);
  if (code) { var inner = code[2].trim(); if (inner && inner.indexOf('`') === -1) return inner; }
  if (t.indexOf('[[') === 0 && t.length > 4 && t.slice(-2) === ']]') {
    var w = t.slice(2, -2).trim();
    if (w && w.indexOf('[[') === -1 && w.indexOf(']]') === -1) return w;
  }
  return t;
}
function canon(raw) {
  var fallback = String(raw == null ? '' : raw).trim();
  var t = String(raw == null ? '' : raw);
  if (typeof t.normalize === 'function') t = t.normalize('NFC');
  t = t.trim();
  if (!t) return fallback;
  for (var q = 0; q < 4; q++) { var before = t; t = unwrapWhole(t); if (t === before) break; }
  var NOTE_EXT = /\.(md|markdown|mdx|txt|org)$/i;
  if (NOTE_EXT.test(t)) {
    t = t.replace(NOTE_EXT, '');
    var cut = Math.max(t.lastIndexOf('/'), t.lastIndexOf('\\'));
    if (cut >= 0) t = t.slice(cut + 1);
  }
  t = t.replace(/\s+/g, ' ').trim();
  return t || fallback;
}
var seen = {};
var items = [];
// 一張卡的 entity 上限：超過的這次不查（也就不處理），避免單張卡把子請求數撐爆。
var MAX_ENTITIES = 200;
for (var i = 0; i < entities.length && items.length < MAX_ENTITIES; i++) {
  var e = canon(entities[i]);
  if (!e || e === 'knowledge-base' || seen[e]) continue;
  seen[e] = true;
  // 給 URL 用的編碼版；entity 原樣（已收斂）留著給比對。
  items.push({
    entity: e,
    enc: encodeURIComponent(e),
    desc_q: encodeURIComponent('entity-desc://' + e),
    concept_q: encodeURIComponent('entity-concept://' + e),
    library: library,
  });
}
if (items.length === 0) throw new Error('沒有可查的 entity（entities_json 空或全被過濾）');
return { success: true, entity_items: items, entity_count: items.length };

decide.code:
function parse(b) { if (typeof b === 'string') { try { return JSON.parse(b); } catch (e) { return null; } } return b; }
var entity = String(input.entity || '');
var library = String(input.library || 'kb');
var d = parse(input.desc_body);
var c = parse(input.concept_body);
var dRecs = (d && Array.isArray(d.records)) ? d.records : [];
var cRecs = (c && Array.isArray(c.records)) ? c.records : [];
var hasDesc = false;
for (var i = 0; i < dRecs.length; i++) {
  var dv = (dRecs[i] && dRecs[i].values) || {};
  if (String(dv.subject || '') === entity && String(dv.predicate || '') === 'description') hasDesc = true;
}
var concepts = [];
var inLib = false;
var markedConcept = false;
for (var j = 0; j < cRecs.length; j++) {
  var cv = (cRecs[j] && cRecs[j].values) || {};
  var obj = String(cv.object || '');
  if (String(cv.subject || '') !== entity || String(cv.predicate || '') !== '屬於' || !obj) continue;
  markedConcept = true;
  if (concepts.indexOf(obj) === -1) concepts.push(obj);
  if (String(cv.library || '') === library) inLib = true;
}
var truncated = (d ? Number(d.total) > dRecs.length : false) || (c ? Number(c.total) > cRecs.length : false);
return {
  success: true,
  entity: entity,
  has_desc: hasDesc,
  in_lib_concept: inLib,
  concepts: concepts,
  truncated: truncated,
  seen: dRecs.length + cRecs.length,
  legacy: false,
  branch: (hasDesc && markedConcept) ? 'false' : 'true',
};

