function parse(b) { if (typeof b === 'string') { try { return JSON.parse(b); } catch (e) { return null; } } return b; }
var base = (input.base && typeof input.base === 'object') ? input.base : {};
var entity = String(input.entity || '');
var library = String(input.library || 'kb');
var l = parse(input.legacy_body);
var recs = (l && Array.isArray(l.records)) ? l.records : [];
var hasDesc = !!base.has_desc;
var inLib = !!base.in_lib_concept;
var concepts = Array.isArray(base.concepts) ? base.concepts.slice() : [];
for (var i = 0; i < recs.length; i++) {
  var v = (recs[i] && recs[i].values) || {};
  if (String(v.subject || '') !== entity) continue;
  var pred = String(v.predicate || '');
  var obj = String(v.object || '');
  if (pred === 'description') hasDesc = true;
  if (pred === '屬於' && obj) {
    if (concepts.indexOf(obj) === -1) concepts.push(obj);
    if (String(v.library || '') === library) inLib = true;
  }
}
var total = l ? Number(l.total) : 0;
return {
  success: true,
  entity: entity,
  has_desc: hasDesc,
  in_lib_concept: inLib,
  concepts: concepts,
  truncated: !!base.truncated || total > recs.length,
  seen: Number(base.seen || 0) + recs.length,
  legacy: true,
};
